description:
This Problem is Just Another Extension of the Factorial Problem But it has Got the Taste of Vast Test Cases Thus You have to Think carefully about multiplication. 

 You Are Given a number 'n' as an Input and You have to find the n! and the n can be in range 0 <= n <= 1000 

 C++ SOLUTION: #include <iostream>
using namespace std;

int main () {
        int n;
        cin >> n;
        int result = 1;
        while(n) {
            result *= n;
            n--;
        }
        cout << result;
        return 0;
}    

 JAVA SOLUTION: import java.io.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int num = Integer.parseInt(br.readLine());

        BigInteger factorial = BigInteger.ONE;

        for (int i = 2; i <= num; i++) {
            factorial = factorial.multiply(BigInteger.valueOf(i));
        }

        System.out.println(factorial);
    }
}


 Js SOLUTION:   let input = '';

process.stdin.on('data', function (chunk) {
  input += chunk;
});

process.stdin.on('end', function () {
  const num = parseInt(input.trim());

  if (isNaN(num) || num < 0) {
    console.log('Please enter a valid non-negative integer.');
    return;
  }

  let factorial = 1;
  for (let i = 1; i <= num; i++) {
    factorial *= i;
  }

  console.log(factorial);
});


